def load() -> pd.DataFrame:
    import pandas as pd
    paths = [
        'data/astronomy/input/geomag_forecast/0311geomag_forecast.txt',
        'data/astronomy/input/geomag_forecast/0312geomag_forecast.txt',
        'data/astronomy/input/geomag_forecast/0313geomag_forecast.txt',
    ]
    rows = []
    for path in paths:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            lines = [ln.rstrip('\n') for ln in f]
        for i, ln in enumerate(lines):
            rows.append({'source_file': path.split('/')[-1], 'line_no': i, 'line': ln})
    return pd.DataFrame(rows)
